/// Each cell's place in a paradigm.
#[allow(dead_code)]
pub mod cell {
    pub const NOM_SG: u16 = 0;
    pub const NOM_PL: u16 = 1;
    pub const ACC_SG: u16 = 2;
    pub const ACC_PL: u16 = 3;
    pub const DAT_SG: u16 = 4;
    pub const DAT_PL: u16 = 5;
    pub const LOC_SG: u16 = 6;
    pub const LOC_PL: u16 = 7;
    pub const ABL_SG: u16 = 8;
    pub const ABL_PL: u16 = 9;
    pub const GEN_SG: u16 = 10;
    pub const GEN_PL: u16 = 11;
}

